<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import { ElMessage, ElMessageBox, type FormInstance, type FormRules } from 'element-plus'
import { createUser, deleteUser, listUsers, updateUser, type UserInput } from '../api/users'
import { errorMessage } from '../utils/errors'
import type { User } from '../types/domain'
const query = reactive({ username_contains: '', role: '', is_active: '', page: 1, page_size: 20 })
const rows = ref<User[]>([]); const count = ref(0); const loading = ref(false); const dialog = ref(false); const editing = ref<string | null>(null); const saving = ref(false)
const formRef = ref<FormInstance>()
const form = reactive<UserInput>({ username: '', email: '', display_name: '', password: '', role: 'USER', is_active: true })
const rules: FormRules = {
  username: [{ required: true, message: '请输入用户名', trigger: 'blur' }, { min: 3, max: 150, message: '长度须为 3～150 个字符', trigger: 'blur' }, { pattern: /^[\p{L}\p{N}_.@+-]+$/u, message: '用户名只能包含字母、数字和 _.@+-', trigger: 'blur' }],
  email: [{ required: true, message: '请输入邮箱', trigger: 'blur' }, { type: 'email', message: '邮箱格式不正确', trigger: 'blur' }],
  password: [{ validator: (_rule, value: string, callback: (error?: Error) => void) => {
    if (editing.value && !value) return callback()
    if (!value || value.length < 8 || value.length > 128) return callback(new Error('密码须为 8～128 个字符'))
    callback()
  }, trigger: 'blur' }],
}
async function load() { loading.value = true; try { const data = await listUsers({ username_contains: query.username_contains || undefined, role: query.role || undefined, is_active: query.is_active || undefined, page: query.page, page_size: query.page_size }); rows.value = data.results; count.value = data.count } catch (error) { ElMessage.error(errorMessage(error)) } finally { loading.value = false } }
function search() { query.page = 1; void load() }
function open(row?: User) { editing.value = row?.id ?? null; Object.assign(form, row ? { username: row.username, email: row.email, display_name: row.display_name, password: '', role: row.role, is_active: row.is_active } : { username: '', email: '', display_name: '', password: '', role: 'USER', is_active: true }); dialog.value = true }
async function save() { if (!await formRef.value?.validate().catch(() => false)) return; saving.value = true; try { if (editing.value) { const payload: Partial<UserInput> = { username: form.username, email: form.email, display_name: form.display_name, role: form.role, is_active: form.is_active }; if (form.password) payload.password = form.password; await updateUser(editing.value, payload) } else { await createUser({ ...form }) } ElMessage.success('保存成功'); dialog.value = false; await load() } catch (error) { ElMessage.error(errorMessage(error)) } finally { saving.value = false } }
async function remove(row: User) { try { await ElMessageBox.confirm(`确定归档用户「${row.username}」？此操作会停用账户。`, '二次确认', { type: 'warning', confirmButtonText: '确认归档', cancelButtonText: '取消' }); await deleteUser(row.id); ElMessage.success('用户已归档'); if (rows.value.length === 1 && query.page > 1) query.page -= 1; await load() } catch (error) { if (error !== 'cancel' && error !== 'close') ElMessage.error(errorMessage(error)) } }
onMounted(load)
</script>
<template><div class="page-head"><div><h1>用户管理</h1><p>查询、创建、编辑和归档账户</p></div><el-button type="primary" @click="open()">新增用户</el-button></div><div class="panel"><div class="toolbar"><el-input v-model="query.username_contains" placeholder="用户名模糊查询" clearable @keyup.enter="search" /><el-select v-model="query.role" placeholder="全部角色" clearable><el-option label="普通用户" value="USER" /><el-option label="管理员" value="ADMIN" /></el-select><el-select v-model="query.is_active" placeholder="全部状态" clearable><el-option label="启用" value="true" /><el-option label="停用" value="false" /></el-select><el-button type="primary" @click="search">查询</el-button></div><el-table v-loading="loading" :data="rows" stripe><el-table-column prop="username" label="用户名" min-width="130" /><el-table-column prop="display_name" label="显示名称" min-width="120" /><el-table-column prop="email" label="邮箱" min-width="190" /><el-table-column prop="role" label="角色" width="100" /><el-table-column label="状态" width="90"><template #default="scope">{{ scope.row.is_active ? '启用' : '停用' }}</template></el-table-column><el-table-column label="操作" width="145"><template #default="scope"><el-button link type="primary" @click="open(scope.row)">编辑</el-button><el-button link type="danger" @click="remove(scope.row)">归档</el-button></template></el-table-column></el-table><div class="pager"><el-pagination v-model:current-page="query.page" :page-size="query.page_size" :total="count" layout="total, prev, pager, next" @current-change="load" /></div></div>
<el-dialog v-model="dialog" :title="editing ? '编辑用户' : '新增用户'" width="520px" destroy-on-close><el-form ref="formRef" :model="form" :rules="rules" label-width="90px"><el-form-item label="用户名" prop="username"><el-input v-model="form.username" maxlength="150" /></el-form-item><el-form-item label="邮箱" prop="email"><el-input v-model="form.email" maxlength="254" /></el-form-item><el-form-item label="显示名称" prop="display_name"><el-input v-model="form.display_name" maxlength="100" /></el-form-item><el-form-item :label="editing ? '新密码' : '密码'" prop="password"><el-input v-model="form.password" type="password" show-password :placeholder="editing ? '不填写则保持原密码' : '至少 8 个字符'" /></el-form-item><el-form-item label="角色"><el-select v-model="form.role"><el-option label="普通用户" value="USER" /><el-option label="管理员" value="ADMIN" /></el-select></el-form-item><el-form-item label="账户状态"><el-switch v-model="form.is_active" /></el-form-item></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" :loading="saving" @click="save">保存</el-button></template></el-dialog></template>
